13	const JWT_SECRET = new TextEncoder().encode(process.env.JWT_SECRET);
14	const AUTH_COOKIE_NAME = "auth_token";
15	const PHONE_VERIFY_COOKIE_NAME = "student_phone_verify";
16	
17	export interface JWTPayload {
18	  id: string;
19	  email: string;
20	  name: string;
21	  role: string;
22	  /** True for the owner superadmin (Ahmed) and the break-glass master login. */
23	  isOwner?: boolean;
24	  deviceId?: string;
25	  iat?: number;
26	  exp?: number;
27	}
