47	type PhoneChallengePayload = {
48	  phone: string;
49	  codeHash?: string;
50	  method?: string;
51	  iat?: number;
52	  exp?: number;
53	};
54	
55	export async function signToken(payload: Omit<JWTPayload, "iat" | "exp">) {
56	  const days = await getConfigNumberClamped("jwt_expiry_days", 1, 365); // was 7d; never 0/NaN
57	  return new SignJWT(payload as Record<string, unknown>)
58	    .setProtectedHeader({ alg: "HS256" })
59	    .setIssuedAt()
60	    .setExpirationTime(`${days}d`)
61	    .sign(JWT_SECRET);
62	}
63	
64	export async function verifyToken(token: string): Promise<JWTPayload | null> {
65	  try {
66	    const { payload } = await jwtVerify(token, JWT_SECRET);
67	    return payload as unknown as JWTPayload;
68	  } catch {
69	    return null;
70	  }
71	}
