218	type SessionOptions = {
219	  preferStudent?: boolean;
220	};
221	
222	function isStudentRole(role: string) {
223	  return role === "student";
224	}
225	
226	export async function getSession(options?: SessionOptions): Promise<SessionUser | null> {
227	  const session = await getJwtSession();
228	
229	  if (!session) {
230	    return null;
231	  }
232	
233	  if (options?.preferStudent && !isStudentRole(session.role)) {
234	    return null;
235	  }
236	
237	  return session;
238	}
239	
240	export async function getStudentSession(): Promise<SessionUser | null> {
241	  return getSession({ preferStudent: true });
242	}
243	
244	export async function getSessionWithRetry(
245	  maxRetries = 3,
246	  delayMs = 100,
247	  options?: SessionOptions
248	): Promise<SessionUser | null> {
249	  for (let attempt = 0; attempt < maxRetries; attempt++) {
250	    const session = await getSession(options);
251	    if (session) {
252	      return session;
253	    }
254	    if (attempt < maxRetries - 1) {
255	      await new Promise((resolve) => setTimeout(resolve, delayMs * (attempt + 1)));
256	    }
257	  }
258	  return null;
259	}
260	
261	export async function getStudentSessionWithRetry(maxRetries = 3, delayMs = 80): Promise<SessionUser | null> {
262	  return getSessionWithRetry(maxRetries, delayMs, { preferStudent: true });
263	}
