10	export async function POST(req: NextRequest) {
11	  try {
12	    const body = (await req.json().catch(() => ({}))) as { phone?: string; password?: string; recaptchaToken?: string };
13	    const { phone, password, recaptchaToken } = body;
14	
15	    // ── reCAPTCHA Enterprise verification ──────────────────────────────────────
16	    if (recaptchaToken) {
17	      const captcha = await verifyRecaptchaToken(recaptchaToken, "login");
18	      if (!captcha.success) {
19	        console.warn("[reCAPTCHA] Login blocked — score:", captcha.score, "reasons:", captcha.reasons);
20	        return NextResponse.json({ error: "تم اكتشاف نشاط مشبوه. يرجى المحاولة مرة أخرى." }, { status: 403 });
21	      }
22	    }
23	
24	    if (!phone || !password) {
25	      return NextResponse.json({ error: "رقم الهاتف وكلمة المرور مطلوبان" }, { status: 400 });
26	    }
27	
28	    const normalizedPhone = normalizeEgyptPhone(String(phone));
29	
30	    const user = await prisma.user.findFirst({ where: { phone: normalizedPhone } });
31	    if (!user) {
32	      return NextResponse.json({ error: "بيانات الدخول غير صحيحة" }, { status: 401 });
33	    }
34	
35	    if (!user.password) {
36	      return NextResponse.json({ error: "بيانات الدخول غير صحيحة" }, { status: 401 });
37	    }
38	
39	    const valid = await bcrypt.compare(password, user.password);
40	    if (!valid) {
41	      return NextResponse.json({ error: "بيانات الدخول غير صحيحة" }, { status: 401 });
42	    }
43	
44	    if (user.role !== "student") {
45	      return NextResponse.json({ error: "استخدم لوحة الإدارة لتسجيل الدخول" }, { status: 403 });
46	    }
47	
48	    // ── Device lock: bind the account to a limited number of devices ──────────
49	    const { deviceId, isNew } = await readDeviceId();
50	    const ipAddress = req.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ?? null;
51	    const userAgent = req.headers.get("user-agent") ?? null;
52	
53	    const known = await prisma.device.findUnique({
54	      where: { userId_deviceId: { userId: user.id, deviceId } },
55	    });
56	    if (known) {
57	      await prisma.device.update({
58	        where: { id: known.id },
59	        data: { lastSeenAt: new Date(), ipAddress, userAgent },
60	      });
61	    } else {
62	      const maxDevices = await getStudentMaxDevices();
63	      const count = await prisma.device.count({ where: { userId: user.id } });
64	      if (count >= maxDevices) {
65	        return NextResponse.json(
66	          {
67	            error: `لقد سجّلت الدخول من الحد الأقصى للأجهزة المسموح بها (${maxDevices}). تواصل مع معلمك لإعادة ضبط الأجهزة.`,
68	            code: "DEVICE_LIMIT",
69	          },
70	          { status: 403 }
71	        );
72	      }
