13	function normalizeStage(value: string) {
14	  return value.trim();
15	}
16	
17	function generateReferralCode(): string {
18	  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
19	  return Array.from({ length: 8 }, () => chars[Math.floor(Math.random() * chars.length)]).join("");
20	}
