22	export async function POST(req: NextRequest) {
23	  try {
24	    const body = await req.json();
25	    const { name, password, phone, parentPhone, age, educationalStage, verificationCode, referralCode, promoCode, teacherPromoCode } = body;
26	
27	    if (!name || !password || !phone || !parentPhone || !age || !educationalStage) {
28	      return NextResponse.json({ error: "جميع الحقول مطلوبة" }, { status: 400 });
29	    }
30	
31	    const normalizedPhone = normalizeEgyptPhone(String(phone));
32	    const normalizedParentPhone = normalizeEgyptPhone(String(parentPhone));
33	
34	    if (normalizedPhone === normalizedParentPhone) {
35	      return NextResponse.json({ error: "رقم المتعلم لا يمكن أن يساوي رقم ولي الأمر" }, { status: 400 });
36	    }
37	
38	    if (!isPhoneVerificationBypassed()) {
39	      if (!verificationCode) {
40	        return NextResponse.json({ error: "رمز التحقق مطلوب" }, { status: 400 });
41	      }
42	      const isValid = await verifyPhoneVerificationCookie(normalizedPhone, String(verificationCode));
43	      if (!isValid) {
44	        return NextResponse.json({ error: "رمز التحقق غير صحيح أو منتهي الصلاحية" }, { status: 400 });
45	      }
46	    }
47	
48	    const generatedEmail = `${normalizedPhone.replace("+", "")}@students.code-up.tech`;
49	
50	    const existing = await prisma.user.findFirst({
51	      where: {
52	        OR: [{ email: generatedEmail }, { phone: normalizedPhone }],
53	      },
54	    });
55	
56	    if (existing) {
57	      return NextResponse.json({ error: "هذا الرقم مسجل بالفعل" }, { status: 409 });
58	    }
59	
60	    const hashed = await bcrypt.hash(password, 12);
61	    const parsedAge = Number(age);
62	    if (!Number.isFinite(parsedAge) || parsedAge < 6 || parsedAge > 25) {
63	      return NextResponse.json({ error: "العمر غير صالح" }, { status: 400 });
64	    }
65	
66	    // Resolve teacher referral if promoCode or teacherPromoCode was supplied
67	    const promoCodeInput = (promoCode || teacherPromoCode || body.promo_code);
68	    let referredByTeacherId: string | undefined;
69	    let promoCodeUsed: string | undefined;
70	
71	    if (promoCodeInput) {
72	      const codeUpper = String(promoCodeInput).trim().toUpperCase();
73	      const teacher = await prisma.user.findFirst({
74	        where: {
75	          role: "teacher",
76	          promoProgramEnabled: true,
77	          promoCode: codeUpper,
78	        },
79	        select: { id: true, promoCodeCreatedAt: true },
80	      });
81	
82	      if (teacher && teacher.promoCodeCreatedAt) {
83	        const now = new Date();
84	        const expiryDate = new Date(teacher.promoCodeCreatedAt.getTime() + 350 * 24 * 60 * 60 * 1000);
85	        if (now <= expiryDate) {
86	          referredByTeacherId = teacher.id;
87	          promoCodeUsed = codeUpper;
88	        }
89	      }
90	    } else {
91	      // Auto-attribute if student joined after visiting a teacher's page
92	      const teacherRefCookie = req.cookies.get("teacher_ref")?.value;
93	      if (teacherRefCookie) {
94	        const teacher = await prisma.user.findFirst({
95	          where: {
96	            id: teacherRefCookie,
97	            role: "teacher",
98	            promoProgramEnabled: true,
99	            isDeleted: false,
100	          },
101	          select: { id: true, promoCode: true },
102	        });
103	
104	        if (teacher) {
105	          referredByTeacherId = teacher.id;
106	          promoCodeUsed = teacher.promoCode || "PAGE_VISIT";
107	        }
108	      }
109	    }
110	
111	    // Resolve referrer if a valid student referral code was supplied
112	    let referredById: string | undefined;
113	    if (referralCode) {
114	      const referrer = await prisma.user.findUnique({
115	        where: { referralCode: String(referralCode).trim().toUpperCase() },
116	        select: { id: true },
117	      });
118	      if (referrer) referredById = referrer.id;
119	    }
120	
121	    // Generate a unique referral code for the new user
122	    let newReferralCode: string;
123	    do {
124	      newReferralCode = generateReferralCode();
125	    } while (await prisma.user.findUnique({ where: { referralCode: newReferralCode }, select: { id: true } }));
126	
127	    const user = await prisma.user.create({
128	      data: {
129	        name: String(name).trim(),
130	        email: generatedEmail,
131	        password: hashed,
132	        phone: normalizedPhone,
133	        parentPhone: normalizedParentPhone,
134	        age: parsedAge,
135	        educationalStage: normalizeStage(String(educationalStage)),
136	        role: "student",
137	        profileCompleted: true,
138	        referralCode: newReferralCode,
139	        referredById,
140	        referredByTeacherId,
141	      },
142	    });
143	
144	    if (referredByTeacherId) {
145	      await prisma.teacherReferralAttribution.create({
146	        data: {
147	          teacherId: referredByTeacherId,
148	          studentId: user.id,
149	          purchaseType: "SIGNUP",
150	          amount: 0,
151	          promoCodeUsed,
152	        },
153	      }).catch(() => {});
154	    }
155	
156	    // Save referral link in PENDING state (referral points are awarded only upon qualified enrollment/course redemption)
157	    if (referredById) {
158	      const { ReferralService } = await import("@/services/referral/ReferralService");
159	      await ReferralService.registerPendingReferral(referredById, user.id);
160	    }
161	
162	    const token = await signToken({ id: user.id, email: user.email, name: user.name, role: user.role });
163	    await setAuthCookie(token);
164	    await clearPhoneVerificationCookie();
165	
166	    return NextResponse.json({
167	      user: {
168	        id: user.id,
169	        name: user.name,
170	        role: user.role,
171	        phone: user.phone,
172	        age: user.age,
173	        educationalStage: user.educationalStage,
174	        profileCompleted: user.profileCompleted,
175	      },
176	    }, { status: 201 });
177	  } catch (err) {
178	    console.error("Signup error:", err);
179	    return NextResponse.json({ error: "حدث خطأ في الخادم" }, { status: 500 });
180	  }
181	}

