39	export async function DELETE() {
40	  const session = await getSession();
41	
42	  if (!session) {
43	    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
44	  }
45	
46	  try {
47	    const user = await prisma.user.findUnique({
48	      where: { id: session.id },
49	    });
50	
51	    if (user) {
52	      await prisma.user.delete({ where: { id: user.id } });
