1	import { prisma } from "@/lib/prisma";
2	import { OtpQuotaManager, OtpActionCategory } from "./OtpQuotaManager";
3	import { sendVerificationSms } from "@/lib/aws-sms";
4	import { createPhoneVerificationChallenge, setPhoneVerificationCookie } from "@/lib/auth";
5	
6	export interface RequestOtpParams {
7	  userId?: string;
8	  phone: string;
9	  actionCategory: OtpActionCategory;
10	}
11	
12	export interface RequestOtpResult {
13	  sent: boolean;
14	  deferred: boolean;
15	  code?: string;
16	  message: string;
17	  quotaRemaining: number;
18	}
19	
20	const ACTION_PRIORITY: Record<OtpActionCategory, number> = {
21	  PASSWORD_RESET: 1,  // Highest priority
22	  COURSE_PURCHASE: 2,
23	  CODE_REDEMPTION: 3,
24	  PHONE_CHANGE: 4,
25	  SIGNUP: 5,          // Lowest priority
26	};
27	
28	export class OtpService {
29	  /**
30	   * Request OTP dispatch.
31	   * If daily WhatsApp quota (< 250) is available:
32	   *   - Atomically reserves quota slot and dispatches SMS/WhatsApp.
33	   * If daily quota is exhausted:
34	   *   - Defers verification, enqueues request into OtpQueueItem with priority ranking,
35	   *     and returns deferred status so user profile can proceed in unverified mode.
36	   */
37	  public static async requestOtp(params: RequestOtpParams): Promise<RequestOtpResult> {
38	    const { userId, phone, actionCategory } = params;
39	
40	    // 1. Reserve quota slot atomically
41	    const quotaRes = await OtpQuotaManager.reserveQuota(actionCategory);
42	
43	    // Generate random 6-digit OTP code
44	    const otpCode = Math.floor(100000 + Math.random() * 900000).toString();
45	
46	    if (quotaRes.allowed) {
47	      // Quota available -> Send WhatsApp OTP immediately
48	      try {
49	        await sendVerificationSms(phone, otpCode);
50	        const challengeToken = await createPhoneVerificationChallenge(phone, otpCode);
51	        await setPhoneVerificationCookie(challengeToken);
52	
53	        return {
54	          sent: true,
55	          deferred: false,
56	          code: otpCode,
57	          message: "تم إرسال رمز التحقق عبر WhatsApp بنجاح",
58	          quotaRemaining: quotaRes.remaining,
59	        };
60	      } catch (err) {
61	        console.error("[OtpService] Failed to send WhatsApp OTP:", err);
62	        // Release reserved quota slot so unused quota isn't wasted
63	        await OtpQuotaManager.releaseQuota(actionCategory);
64	      }
65	    }
66	
67	    // 2. Daily quota exhausted OR provider call failed -> Defer verification
68	    if (userId) {
69	      const priority = ACTION_PRIORITY[actionCategory] ?? 5;
70	
71	      await prisma.otpQueueItem.create({
72	        data: {
73	          userId,
74	          phone,
75	          actionType: actionCategory,
76	          priority,
77	          status: "QUEUED",
78	        },
79	      });
80	
81	      // Update user verification status to WAITING_FOR_OTP
82	      await prisma.user.update({
83	        where: { id: userId },
84	        data: {
85	          isVerified: false,
86	          verificationStatus: "WAITING_FOR_OTP",
87	        },
88	      });
89	    }
90	
91	    return {
92	      sent: false,
93	      deferred: true,
94	      message: "تم بلوغ الحد اليومي لرسائل التحقق السريعة. تم إدراج طلبك في قائمة الانتظار، ويمكنك متابعة استخدام حسابك الآن.",
95	      quotaRemaining: 0,
96	    };
97	  }
98	
99	  /**
100	   * Worker method called by cron or admin trigger to process queued OTP items
101	   * whenever daily quota becomes available.
102	   */
103	  public static async processQueuedOtps(maxBatchSize: number = 20): Promise<{
104	    processed: number;
105	    sent: number;
106	    failed: number;
107	  }> {
108	    let sentCount = 0;
109	    let failedCount = 0;
110	
111	    // Fetch queued items ordered by priority (1 highest) and queue timestamp
112	    const queuedItems = await prisma.otpQueueItem.findMany({
113	      where: { status: "QUEUED" },
114	      orderBy: [{ priority: "asc" }, { queuedAt: "asc" }],
115	      take: maxBatchSize,
116	    });
117	
118	    for (const item of queuedItems) {
119	      // Check quota reservation for item's action
120	      const quotaRes = await OtpQuotaManager.reserveQuota(item.actionType as OtpActionCategory);
121	      if (!quotaRes.allowed) {
122	        // Quota still exhausted -> Stop processing batch
123	        break;
124	      }
125	
126	      try {
127	        const otpCode = Math.floor(100000 + Math.random() * 900000).toString();
128	        await sendVerificationSms(item.phone, otpCode);
129	
130	        // Update queue item
131	        await prisma.otpQueueItem.update({
132	          where: { id: item.id },
133	          data: {
134	            status: "SENT",
135	            processedAt: new Date(),
136	          },
137	        });
138	
139	        // Update user to VERIFIED
140	        await prisma.user.update({
141	          where: { id: item.userId },
142	          data: {
143	            isVerified: true,
144	            verificationStatus: "VERIFIED",
145	          },
146	        });
147	
148	        sentCount++;
149	      } catch (err) {
150	        console.error(`[OtpService] Processing queued item ${item.id} failed:`, err);
151	        failedCount++;
152	
153	        await prisma.otpQueueItem.update({
154	          where: { id: item.id },
155	          data: {
156	            retryCount: { increment: 1 },
157	            status: item.retryCount >= 3 ? "FAILED" : "QUEUED",
158	          },
159	        });
160	      }
161	    }
162	
163	    return {
164	      processed: queuedItems.length,
165	      sent: sentCount,
166	      failed: failedCount,
167	    };
168	  }
169	}

1	import { prisma } from "@/lib/prisma";
2	
3	export type OtpActionCategory =
4	  | "SIGNUP"
5	  | "PASSWORD_RESET"
6	  | "COURSE_PURCHASE"
7	  | "PHONE_CHANGE"
8	  | "CODE_REDEMPTION";
9	
10	export interface QuotaCheckResult {
11	  allowed: boolean;
12	  used: number;
13	  remaining: number;
14	  limit: number;
15	}
16	
17	export class OtpQuotaManager {
18	  /**
19	   * Returns Cairo calendar date string YYYY-MM-DD.
20	   */
21	  public static getCairoTodayStr(date: Date = new Date()): string {
22	    return date.toLocaleDateString("en-CA", { timeZone: "Africa/Cairo" });
23	  }
24	
25	  /**
26	   * Atomically checks and reserves daily WhatsApp OTP quota inside a transaction.
27	   * Hard limit: 250 calls per Cairo calendar day.
28	   */
29	  public static async reserveQuota(
30	    category: OtpActionCategory,
31	    limit: number = 250
32	  ): Promise<QuotaCheckResult> {
33	    const todayStr = this.getCairoTodayStr();
34	
35	    return await prisma.$transaction(async (tx) => {
36	      // Find or create today's quota record
37	      let quotaRecord = await tx.otpQuota.findUnique({
38	        where: { date: todayStr },
39	      });
40	
41	      if (!quotaRecord) {
42	        quotaRecord = await tx.otpQuota.create({
43	          data: {
44	            date: todayStr,
45	            limit,
46	            used: 0,
47	          },
48	        });
49	      }
50	
51	      // Reserve 30 OTPs strictly for PASSWORD_RESET so users can ALWAYS recover accounts
52	      const PASSWORD_RESET_RESERVED = 30;
53	      const generalLimit = quotaRecord.limit - PASSWORD_RESET_RESERVED; // 220 for general use
54	
55	      if (category !== "PASSWORD_RESET" && quotaRecord.used >= generalLimit) {
56	        return {
57	          allowed: false,
58	          used: quotaRecord.used,
59	          remaining: 0,
60	          limit: quotaRecord.limit,
61	        };
62	      }
63	
64	      if (quotaRecord.used >= quotaRecord.limit) {
65	        return {
66	          allowed: false,
67	          used: quotaRecord.used,
68	          remaining: 0,
69	          limit: quotaRecord.limit,
70	        };
71	      }
72	
73	      // Map action category to column field
74	      const categoryFieldMap: Record<OtpActionCategory, string> = {
75	        SIGNUP: "signupUsed",
76	        PASSWORD_RESET: "forgotPasswordUsed",
77	        COURSE_PURCHASE: "purchaseUsed",
78	        PHONE_CHANGE: "phoneChangeUsed",
79	        CODE_REDEMPTION: "codeRedemptionUsed",
80	      };
81	
82	      const categoryField = categoryFieldMap[category] || "signupUsed";
83	
84	      // Atomically increment quota
85	      const updated = await tx.otpQuota.update({
86	        where: { id: quotaRecord.id },
87	        data: {
88	          used: { increment: 1 },
89	          [categoryField]: { increment: 1 },
90	        },
91	      });
92	
93	      return {
94	        allowed: true,
95	        used: updated.used,
96	        remaining: Math.max(0, updated.limit - updated.used),
97	        limit: updated.limit,
98	      };
99	    });
100	  }
101	
102	  /**
103	   * Releases a reserved OTP quota slot if the WhatsApp provider call fails.
104	   */
105	  public static async releaseQuota(category: OtpActionCategory): Promise<void> {
106	    const todayStr = this.getCairoTodayStr();
107	    const categoryFieldMap: Record<OtpActionCategory, string> = {
108	      SIGNUP: "signupUsed",
109	      PASSWORD_RESET: "forgotPasswordUsed",
110	      COURSE_PURCHASE: "purchaseUsed",
111	      PHONE_CHANGE: "phoneChangeUsed",
112	      CODE_REDEMPTION: "codeRedemptionUsed",
113	    };
114	
115	    const categoryField = categoryFieldMap[category] || "signupUsed";
116	
117	    await prisma.otpQuota.updateMany({
118	      where: { date: todayStr, used: { gt: 0 } },
119	      data: {
120	        used: { decrement: 1 },
121	        [categoryField]: { decrement: 1 },
122	      },
123	    }).catch(() => {});
124	  }
125	
126	  /**
127	   * Queries today's current OTP quota status without incrementing.
128	   */
129	  public static async getTodayQuotaStats(): Promise<{
130	    date: string;
131	    used: number;
132	    remaining: number;
133	    limit: number;
134	    signupUsed: number;
135	    forgotPasswordUsed: number;
136	    purchaseUsed: number;
137	    phoneChangeUsed: number;
138	    codeRedemptionUsed: number;
139	  }> {
140	    const todayStr = this.getCairoTodayStr();
141	    const quota = await prisma.otpQuota.findUnique({
142	      where: { date: todayStr },
143	    });
144	
145	    const limit = quota?.limit ?? 250;
146	    const used = quota?.used ?? 0;
147	
148	    return {
149	      date: todayStr,
150	      used,
151	      remaining: Math.max(0, limit - used),
152	      limit,
153	      signupUsed: quota?.signupUsed ?? 0,
154	      forgotPasswordUsed: quota?.forgotPasswordUsed ?? 0,
155	      purchaseUsed: quota?.purchaseUsed ?? 0,
156	      phoneChangeUsed: quota?.phoneChangeUsed ?? 0,
157	      codeRedemptionUsed: quota?.codeRedemptionUsed ?? 0,
158	    };
159	  }
160	}

