1	const cooldowns = new Map<string, number>();
2	
3	/**
4	 * Checks if the request is allowed for a given phone number.
5	 * If allowed, sets the cooldown timestamp and returns true.
6	 * If not allowed, returns false with the remaining seconds.
7	 */
8	export function checkCooldown(
9	  phone: string,
10	  cooldownMs = 60000
11	): { allowed: boolean; remainingSeconds: number } {
12	  const now = Date.now();
13	
14	  // Clean up expired entries to prevent memory leaks
15	  for (const [key, val] of cooldowns.entries()) {
16	    if (now - val >= cooldownMs) {
17	      cooldowns.delete(key);
18	    }
19	  }
20	
21	  const lastSent = cooldowns.get(phone);
22	  if (lastSent && now - lastSent < cooldownMs) {
23	    const remainingSeconds = Math.ceil((cooldownMs - (now - lastSent)) / 1000);
24	    return { allowed: false, remainingSeconds };
25	  }
26	
27	  // Update/Set timestamp
28	  cooldowns.set(phone, now);
29	  return { allowed: true, remainingSeconds: 0 };
30	}

