17	export interface RecaptchaResult {
18	  /** Whether the token passed basic validation (score >= threshold). */
19	  success: boolean;
20	  /** Risk score from 0.0 (likely bot) to 1.0 (likely human). */
21	  score: number;
22	  /** Reason codes returned by the API (e.g. "BROWSER_ERROR"). */
23	  reasons: string[];
24	  /** Raw assessment name (useful for annotation). */
25	  assessmentName?: string;
26	}
