28	/**
29	 * Verify a reCAPTCHA Enterprise token on the server.
30	 *
31	 * @param token        The token produced by grecaptcha.enterprise.execute()
32	 * @param expectedAction  The action string you passed to execute(), e.g. "login"
33	 * @param scoreThreshold  Minimum score to consider valid (default 0.5)
34	 */
35	export async function verifyRecaptchaToken(
36	  token: string,
37	  expectedAction: string,
38	  scoreThreshold = 0.5
39	): Promise<RecaptchaResult> {
40	  // Allow bypass in dev/testing mode when explicitly set or bypass is enabled
41	  if (process.env.RECAPTCHA_BYPASS === "true") {
42	    return { success: true, score: 1, reasons: ["BYPASS"] };
43	  }
44	
45	  const apiKey = process.env.RECAPTCHA_API_KEY;
46	
47	  // If no API key is configured, skip verification gracefully (dev / CI).
48	  if (!apiKey) {
49	    console.warn("[reCAPTCHA] RECAPTCHA_API_KEY is not set — skipping verification.");
50	    return { success: true, score: 1, reasons: ["SKIPPED_NO_API_KEY"] };
51	  }
52	
53	  const url = `https://recaptchaenterprise.googleapis.com/v1/projects/${PROJECT_ID}/assessments?key=${apiKey}`;
54	
55	  const body = {
56	    event: {
57	      token,
58	      expectedAction,
59	      siteKey: SITE_KEY,
60	    },
61	  };
62	
63	  let data: any;
64	  try {
65	    const res = await fetch(url, {
66	      method: "POST",
67	      headers: { "Content-Type": "application/json" },
68	      body: JSON.stringify(body),
69	    });
70	    data = await res.json();
71	  } catch (err) {
72	    console.error("[reCAPTCHA] Network error calling assessment API:", err);
73	    // Fail open so a network blip doesn't lock out all users.
74	    return { success: true, score: 0.5, reasons: ["NETWORK_ERROR"] };
75	  }
76	
77	  // The API returns an error object when the token is invalid or malformed.
78	  if (data?.error) {
79	    console.error("[reCAPTCHA] Assessment API error:", data.error);
80	    return { success: false, score: 0, reasons: ["API_ERROR"] };
81	  }
82	
83	  const tokenProps = data?.tokenProperties ?? {};
84	  const riskAnalysis = data?.riskAnalysis ?? {};
85	  const score: number = riskAnalysis.score ?? 0;
86	  const reasons: string[] = riskAnalysis.reasons ?? [];
87	
88	  // Token must be valid and the action must match what we expected.
89	  if (!tokenProps.valid) {
90	    return { success: false, score: 0, reasons: ["INVALID_TOKEN", ...(tokenProps.invalidReason ? [tokenProps.invalidReason] : []), ...reasons] };
91	  }
92	
93	  if (tokenProps.action && tokenProps.action !== expectedAction) {
94	    return { success: false, score, reasons: ["ACTION_MISMATCH", ...reasons] };
95	  }
96	
97	  return {
98	    success: score >= scoreThreshold,
99	    score,
100	    reasons,
101	    assessmentName: data?.name,
102	  };
103	}

