1	const EGYPT_MOBILE_REGEX = /^01[0-9]{9}$/;
2	
3	export function normalizeEgyptPhone(input: string) {
4	  const raw = String(input || "").trim();
5	  try {
6	    console.log("normalizeEgyptPhone raw:", JSON.stringify(raw), "codes:", Array.from(raw).map((c) => c.charCodeAt(0)));
7	  } catch (e) {
8	    console.log("normalizeEgyptPhone raw (stringify failed)");
9	  }
10	  // convert Arabic-Indic numerals to ASCII digits
11	  const arabicMap: Record<string, string> = {
12	    '\u0660': '0', '\u0661': '1', '\u0662': '2', '\u0663': '3', '\u0664': '4', '\u0665': '5', '\u0666': '6', '\u0667': '7', '\u0668': '8', '\u0669': '9',
13	    '\u06F0': '0', '\u06F1': '1', '\u06F2': '2', '\u06F3': '3', '\u06F4': '4', '\u06F5': '5', '\u06F6': '6', '\u06F7': '7', '\u06F8': '8', '\u06F9': '9',
14	  };
15	  let cleaned = raw.replace(/[\u0660-\u0669\u06F0-\u06F9]/g, (d) => arabicMap[d] || d);
16	  // remove international 00 prefix -> +
17	  cleaned = cleaned.replace(/^00/, "+");
18	  // If the input is already E.164 (starts with +), accept as-is to support non-Egyptian E.164 numbers
19	  if (cleaned.startsWith("+")) {
20	    const digitsOnly = cleaned.replace(/\D/g, "");
21	    // If it's an Egyptian E.164 return normalized +20... format
22	    if (digitsOnly.startsWith("20") && digitsOnly.length === 12) {
23	      return `+${digitsOnly}`;
24	    }
25	    // Otherwise assume caller provided a valid E.164 number (e.g., TWILIO_FROM_NUMBER)
26	    return cleaned;
27	  }
28	  const digits = cleaned.replace(/\D/g, "");
29	
30	  // +20XXXXXXXXXX or 20XXXXXXXXXX
31	  if ((digits.startsWith("20") || digits.startsWith("2")) && digits.length === 12) {
32	    return `+${digits}`;
33	  }
34	
35	  // local 01XXXXXXXXX
36	  if (EGYPT_MOBILE_REGEX.test(digits)) {
37	    return `+20${digits.slice(1)}`;
38	  }
39	
40	  // Fallback: if the digits string contains an occurrence of 01XXXXXXXXX, extract it
41	  const found = digits.match(/01[0-9]{9}/);
42	  if (found) {
43	    const m = found[0];
44	    return `+20${m.slice(1)}`;
45	  }
46	
47	  throw new Error("رقم الهاتف غير صالح. استخدم رقم مصري يبدأ بـ 01");
48	}
