50	export function formatDisplayPhone(input: string) {
51	  const digits = input.replace(/\D/g, "");
52	  if (digits.startsWith("0")) {
53	    return digits;
54	  }
55	  if (digits.startsWith("20") && digits.length === 12) {
56	    return `0${digits.slice(2)}`;
57	  }
58	  if (digits.startsWith("2") && digits.length === 12) {
59	    return `0${digits.slice(2)}`;
60	  }
61	  return input;
62	}

