57	export const CATEGORY_LABELS: Record<string, string> = {
58	  auth: "المصادقة والأمان",
59	  video: "الفيديو والمحتوى",
60	  codes: "أكواد الوصول",
61	  ai: "خطط الذكاء الاصطناعي",
62	  rate: "حدود المعدّل",
63	  storage: "التخزين والتنظيف",
64	};
65	
66	const DEF_BY_KEY = new Map(CONFIG_DEFINITIONS.map((d) => [d.key, d]));
67	
68	/**
69	 * Keys actually wired into runtime behavior. The rest are editable but not yet
70	 * enforced anywhere — the panel badges them so a superadmin doesn't trust a
71	 * setting that currently does nothing.
72	 */
73	const ENFORCED_KEYS = new Set([
74	  "jwt_expiry_days",
75	  "default_max_watches",
76	  "watch_session_hours",
77	  "mark_complete_threshold",
78	  "max_videos_per_folder",
79	  "ai_max_tokens",
80	  "trash_purge_days",
81	]);
82	
83	// ── 60-second in-memory cache of the whole config map ──
84	let cache: Map<string, string> | null = null;
85	let cacheAt = 0;
86	const TTL_MS = 60_000;
87	
88	async function loadAll(): Promise<Map<string, string>> {
89	  if (cache && Date.now() - cacheAt < TTL_MS) return cache;
90	  const map = new Map<string, string>();
91	  for (const d of CONFIG_DEFINITIONS) map.set(d.key, d.default);
92	  try {
93	    const rows = await prisma.platformConfig.findMany();
94	    for (const r of rows) if (DEF_BY_KEY.has(r.key)) map.set(r.key, r.value);
95	  } catch {
96	    /* table missing / db error → defaults only */
97	  }
98	  cache = map;
99	  cacheAt = Date.now();
100	  return map;
101	}
102	
103	/** Drop the cache so the next read reflects a just-saved value. */
104	export function invalidateConfigCache() {
105	  cache = null;
106	  cacheAt = 0;
107	}
108	
109	export async function getConfig(key: string): Promise<string> {
110	  const map = await loadAll();
111	  return map.get(key) ?? DEF_BY_KEY.get(key)?.default ?? "";
112	}
113	
114	export async function getConfigNumber(key: string): Promise<number> {
115	  const n = Number(await getConfig(key));
116	  if (Number.isFinite(n)) return n;
117	  return Number(DEF_BY_KEY.get(key)?.default ?? 0);
118	}
119	
120	export async function getConfigBool(key: string): Promise<boolean> {
121	  return (await getConfig(key)) === "true";
122	}
123	
124	/**
125	 * Safety net for values that feed critical logic: never let a misconfigured
126	 * (or zero/negative) number break login, playback, or — worst case — trigger an
127	 * instant purge. Clamps to [min, max]; falls back to the definition default.
128	 */
129	export async function getConfigNumberClamped(
130	  key: string,
131	  min: number,
132	  max = Number.POSITIVE_INFINITY
133	): Promise<number> {
134	  let n = await getConfigNumber(key);
135	  if (!Number.isFinite(n) || n <= 0) n = Number(DEF_BY_KEY.get(key)?.default ?? min);
136	  return Math.min(Math.max(n, min), max);
137	}
138	
139	/** Validate + persist a single setting, then invalidate the cache. */
140	export async function setConfig(key: string, value: unknown): Promise<void> {
141	  const def = DEF_BY_KEY.get(key);
142	  if (!def) throw new Error("Unknown config key");
143	
144	  let str: string;
145	  if (def.type === "number") {
146	    const n = Number(value);
147	    if (!Number.isFinite(n)) throw new Error("قيمة رقمية غير صالحة");
148	    str = String(n);
149	  } else if (def.type === "boolean") {
150	    str = value === true || value === "true" ? "true" : "false";
151	  } else {
152	    str = String(value ?? "").slice(0, 2000);
153	  }
154	
155	  await prisma.platformConfig.upsert({
156	    where: { key },
157	    update: { value: str, type: def.type, category: def.category, label: def.label },
158	    create: { key, value: str, type: def.type, category: def.category, label: def.label },
159	  });
160	  invalidateConfigCache();
161	}
162	
163	/** Definitions merged with current values, grouped by category — for the panel. */
164	export async function getGroupedConfig() {
165	  const map = await loadAll();
166	  const groups: Record<string, { category: string; label: string; items: Array<ConfigDef & { value: string; enforced: boolean }> }> = {};
167	  for (const d of CONFIG_DEFINITIONS) {
168	    if (!groups[d.category]) {
169	      groups[d.category] = { category: d.category, label: CATEGORY_LABELS[d.category] ?? d.category, items: [] };
170	    }
171	    groups[d.category].items.push({ ...d, value: map.get(d.key) ?? d.default, enforced: ENFORCED_KEYS.has(d.key) });
172	  }
173	  return Object.values(groups);
174	}

