32	function timingSafeCompare(a: string, b: string): boolean {
33	  try {
34	    const aBuf = Buffer.from(a, "utf8");
35	    const bBuf = Buffer.from(b, "utf8");
36	    if (aBuf.length !== bBuf.length) return false;
37	    return timingSafeEqual(aBuf, bBuf);
38	  } catch {
39	    return false;
40	  }
41	}
