43	/**
44	 * Verifies the action password for a given admin role.
45	 * superadmin → SUPERADMIN_ACTION_PASSWORD
46	 * admin      → ADMIN_ACTION_PASSWORD
47	 * staff      → always false (read-only role, no actions)
48	 */
49	export function verifyRoleActionPassword(role: string, password: string): boolean {
50	  if (!password) return false;
51	  const envVar =
52	    role === "superadmin"
53	      ? process.env.SUPERADMIN_ACTION_PASSWORD
54	      : role === "admin"
55	      ? process.env.ADMIN_ACTION_PASSWORD
56	      : null;
57	  if (!envVar) return false;
58	  return timingSafeCompare(password, envVar);
59	}
