19	/**
20	 * Checks if a user has access to a video/lesson.
21	 * - Free videos: accessible to all.
22	 * - Admin/Superadmin: full access.
23	 * - Teacher: access if they own the course.
24	 * - Student: access if they have course-level, folder-level, or video-level access,
25	 *   or plan enrollment that contains the video.
26	 */
27	export async function checkVideoAccess(userId: string, role: string, videoId: string): Promise<boolean> {
28	  if (role === "superadmin" || role === "admin") return true;
29	
30	  const video = await prisma.video.findUnique({
31	    where: { id: videoId },
32	    include: {
33	      folder: {
34	        select: {
35	          id: true,
36	          courseId: true,
37	          course: { select: { teacherId: true } }
38	        }
39	      }
40	    }
41	  });
42	
43	  if (!video) return false;
44	  if (video.isFree) return true;
45	
46	  if (role === "teacher") {
47	    return video.folder.course.teacherId === userId;
48	  }
49	
50	  if (role !== "student") return false;
51	
52	  // 1. Check Course-level access
53	  const enrolled = await checkCourseEnrollment(userId, video.folder.courseId);
54	  if (enrolled) return true;
55	
56	  // 2. Check Folder-level access (AccessCode or Purchase)
57	  const folderId = video.folderId;
58	  const hasFolderAccessCode = await prisma.accessCode.findFirst({
59	    where: {
60	      folderId,
61	      studentId: userId,
62	      accessType: "FOLDER",
63	      isActive: true,
64	    },
65	    select: { id: true }
66	  });
67	  if (hasFolderAccessCode) return true;
68	
69	  const hasFolderPurchase = await prisma.folderPurchase.findUnique({
70	    where: { studentId_folderId: { studentId: userId, folderId } },
71	    select: { id: true }
72	  });
73	  if (hasFolderPurchase) return true;
74	
75	  // 3. Check Video-level access (AccessCode or Purchase)
76	  const hasVideoAccessCode = await prisma.accessCode.findFirst({
77	    where: {
78	      videoId,
79	      studentId: userId,
80	      accessType: "VIDEO",
81	      isActive: true,
82	    },
83	    select: { id: true }
84	  });
85	  if (hasVideoAccessCode) return true;
86	
87	  const hasVideoPurchase = await prisma.videoPurchase.findUnique({
88	    where: { studentId_videoId: { studentId: userId, videoId } },
89	    select: { id: true }
90	  });
91	  if (hasVideoPurchase) return true;
92	
93	  // 4. Check Plan enrollment
94	  const now = new Date();
95	  const hasPlanEnrollment = await prisma.planEnrollment.findFirst({
96	    where: {
97	      studentId: userId,
98	      expiresAt: { gt: now },
99	      plan: {
100	        lessons: {
101	          some: {
102	            sources: {
103	              some: { videoId }
104	            }
105	          }
106	        }
107	      }
108	    },
109	    select: { id: true }
110	  });
111	  if (hasPlanEnrollment) return true;
112	
113	  return false;
114	}
