116	/**
117	 * Checks if a user has access to homework.
118	 * - Admin/Superadmin: full access.
119	 * - Teacher: access if they created the homework.
120	 * - Student: access if they are enrolled in the course the homework belongs to.
121	 */
122	export async function checkHomeworkAccess(userId: string, role: string, homeworkId: string): Promise<boolean> {
123	  if (role === "superadmin" || role === "admin") return true;
124	
125	  const hw = await prisma.homework.findUnique({
126	    where: { id: homeworkId },
127	    select: {
128	      teacherId: true,
129	      courseId: true,
130	      videoId: true,
131	    }
132	  });
133	
134	  if (!hw) return false;
135	
136	  if (role === "teacher") {
137	    return hw.teacherId === userId;
138	  }
139	
140	  if (role !== "student") return false;
141	
142	  let courseId = hw.courseId;
143	  if (!courseId && hw.videoId) {
144	    const video = await prisma.video.findUnique({
145	      where: { id: hw.videoId },
146	      include: { folder: { select: { courseId: true } } }
147	    });
148	    if (video) {
149	      courseId = video.folder.courseId;
150	    }
151	  }
152	
153	  if (!courseId) return false;
154	
155	  return await checkCourseEnrollment(userId, courseId);
156	}

